package com.porquinho.dto;

import com.fasterxml.jackson.annotation.JsonIgnore;
import com.porquinho.service.CategoryService;
import com.porquinho.validation.NotFutureInSaoPaulo;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.UUID;

/**
 * POST /api/v1/transfers (Story 4.5). The id is generated by the client and makes the request idempotent. Both accounts are required and must differ; the amount must be > 0 and fit
 * DECIMAL(15,2); the date is required and may not be after today in America/Sao_Paulo; the description is optional,
 * cleaned once like names (NFC, no Unicode spaces nor format characters at the edges), blank becomes null.
 */
public record CreateTransferRequest(
    /** Generated by the client once per form opening (idempotency key); becomes the transfer id. */
    @NotNull(message = "Identificador da transferência ausente. Feche e abra o formulário de novo.")
    UUID id,

    @NotNull(message = "Escolha a conta de origem")
    UUID fromAccountId,

    @NotNull(message = "Escolha a conta de destino")
    UUID toAccountId,

    @NotNull(message = "Informe o valor da transferência")
    @DecimalMin(value = "0", inclusive = false, message = "O valor precisa ser maior que zero")
    @Digits(integer = 13, fraction = 2,
        message = "Informe o valor com até 2 casas decimais e no máximo 13 dígitos antes da vírgula")
    BigDecimal amount,

    @NotNull(message = "Informe a data da transferência")
    @NotFutureInSaoPaulo(message = "A data não pode estar no futuro")
    LocalDate transferDate,

    @Size(max = 200, message = "Use no máximo 200 caracteres na descrição")
    String description
) {
    public static final String SAME_ACCOUNT_MESSAGE = "Escolha contas diferentes";

    public CreateTransferRequest {
        description = CategoryService.cleanName(description);
        if (description != null && description.isEmpty()) {
            description = null;
        }
    }

    /** Bean Validation property "differentAccounts": origin and destination must not be the same account. */
    @JsonIgnore
    @AssertTrue(message = SAME_ACCOUNT_MESSAGE)
    public boolean isDifferentAccounts() {
        return fromAccountId == null || toAccountId == null || !fromAccountId.equals(toAccountId);
    }
}
